ProjectALife.DialogueShards["scenes_any_7"] = {
{"fw_ld4_quick_i_0009","any",2,"reg=civilian,family,worker,rescue",{1,"We should have a toast",2,"With what?",1,"This sip of water",2,"To what?",1,"To staying thirsty, because it means we're still alive"}},
{"fw_ld4_quick_i_0010","any",2,"reg=civilian,family,worker,rescue",{1,"Think anyone's got a TV on?",2,"Where?",1,"Anywhere, an old man in a bunker, watching reruns",2,"I hope so, I hope someone's laughing at a rerun"}},
{"fw_ld4_quick_i_0011","any",2,"reg=civilian,family,worker,rescue",{1,"How's your sister?",2,"Don't know",1,"Where was she last?",2,"Louisville, the night it started",1,"I'm sorry",2,"Don't be, she's tougher than me, she'll walk out"}},
{"fw_ld4_quick_i_0012","any",2,"reg=civilian,family,worker,rescue",{1,"I'm going to bake a cake when this is over",2,"Chocolate?",1,"Lemon, with a candle",2,"For who?",1,"For everybody still breathing"}},
{"fw_ld4_quick_i_0013","any",2,"reg=civilian,family,worker,rescue",{1,"Hey, tell me a lie",2,"A lie?",1,"A nice one",2,"Tomorrow it'll all be better, you'll see",1,"Thank you, I needed that"}},
{"fw_ld4_quick_i_0014","any",2,"reg=civilian,family,worker,rescue",{1,"Is it wrong to laugh?",2,"Never",1,"Even now?",2,"Especially now, laughing's the one thing they can't take off us"}},
{"fw_ld4_quick_i_0015","any",2,"reg=civilian,family,worker,rescue",{1,"Why do you keep looking behind you?",2,"Habit",1,"From what?",2,"From last week, when I didn't, and paid for it"}},
{"fw_ld4_quick_i_0016","any",2,"reg=civilian,family,worker,rescue|hour=7,18",{1,"Think about warm things",2,"Like what?",1,"Toast, sunshine, a dog's belly",2,"A dog's belly is the warmest thing there is"}},
{"fw_ld4_quick_i_0017","any",2,"reg=civilian,family,worker,rescue",{1,"Remember school lunches?",2,"Mystery meat Mondays",1,"Pizza Fridays",2,"I'd marry a pizza Friday"}},
{"fw_ld4_quick_i_0018","any",2,"reg=civilian,family,worker,rescue",{1,"Do you miss work?",2,"Not one bit",1,"Not even a little?",2,"I miss the coffee, the vending machine, and the guy who sang off-key"}},
{"fw_ld4_quick_i_0019","any",2,"reg=civilian,family,worker,rescue",{1,"What was the first thing you noticed?",2,"The quiet",1,"Same, the whole world went quiet",2,"And then it got loud"}},
{"fw_ld4_quick_i_0020","any",2,"reg=civilian,family,worker,rescue",{1,"I want a hot dog",2,"You always want a hot dog",1,"It's a good thing to want",2,"It's an honest thing to want"}},
{"fw_ld4_quick_i_0021","any",2,"reg=civilian,family,worker,rescue",{1,"Do you pray?",2,"Not really",1,"Do you hope?",2,"Constantly",1,"Same thing, probably"}},
{"fw_ld4_quick_i_0022","any",2,"reg=civilian,family,worker,rescue",{1,"How do I look in this coat?",2,"Like a lamp shade",1,"Rude",2,"A cozy lamp shade"}},
{"fw_ld4_quick_i_0023","any",2,"reg=civilian,family,worker,rescue",{1,"What if I'm not who you think I am?",2,"Then I'll learn who you are",1,"What if you don't like it?",2,"Then I'll like you anyway"}},
{"fw_ld4_quick_i_0024","any",2,"reg=civilian,family,worker,rescue|tmp=fresh|hour=20,5",{1,"I hate it this dark",2,"I know",1,"I can't stand it when it's dark",2,"I know. Me too. Here - hold my sleeve"}},
{"fw_ld4_quick_i_0025","any",2,"reg=civilian,family,worker,rescue|tmp=fresh",{1,"I wish I could be brave like you",2,"I'm not brave",1,"You are",2,"I'm just very good at pretending, and so can you"}},
{"fw_ld4_quick_i_0026","any",2,"reg=civilian,family,worker,rescue|tmp=fresh",{1,"What if nobody comes?",2,"Then we make our own way",1,"How?",2,"One step, then another, repeat"}},
{"fw_ld4_quick_i_0027","any",2,"reg=civilian,family,worker,rescue|tmp=seasoned",{1,"What do you miss?",2,"Being bored",1,"Bored?",2,"Utterly, wonderfully bored, in a waiting room"}},
{"fw_ld4_quick_i_0028","any",2,"reg=law,swat",{1,"Remember the training videos?",2,"The ones with the bad acting?",1,"I'd watch them all night now",2,"Me too, with popcorn"}},
{"fw_ld4_quick_i_0029","any",2,"reg=law,swat",{1,"Everything okay out there?",2,"As okay as it gets",1,"Is that a yes?",2,"It's a 'could be worse'"}},
{"fw_ld4_quick_i_0030","any",2,"reg=law,swat",{1,"What did you want to be?",2,"A firefighter",1,"Why a cop then?",2,"My dad was a cop, and I couldn't disappoint him"}},
{"fw_ld4_quick_i_0031","any",2,"reg=military,elite",{1,"At ease, nobody's watching",2,"Thank you, Sergeant",1,"Stretch your back",2,"It's been aching since Kentucky"}},
{"fw_ld4_quick_i_0032","any",2,"reg=military,elite",{1,"Sergeant, hear that?",2,"Hear what?",1,"Never mind, it's gone",2,"Don't say 'never mind', say what"}},
{"fw_ld4_quick_i_0033","any",2,"reg=military,elite|world=vehicle",{1,"First day out, I cried in the truck",2,"Me too",1,"Don't tell the boys",2,"Tell them what?"}},
{"fw_ld4_quick_i_0034","any",2,"reg=outlaw,raider,gang,club,crime,prison|world=cars",{1,"What did you do before?",2,"I sold used cars",1,"And?",2,"I was a crook then too, just legal"}},
{"fw_ld4_quick_i_0035","any",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"Hey, you hear that?",2,"What?",1,"Someone's laughing",2,"That's us",1,"Oh, I thought we were being haunted"}},
{"fw_ld4_quick_i_0036","any",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"What's your plan?",2,"Survive and steal",1,"That's two plans",2,"They go together"}},
{"fw_ld4_quick_i_0037","any",2,"reg=family",{1,"Papa, will you teach me to whistle?",2,"Sure, c'mere, lips like this",1,"Now?",2,"Pucker up, blow, and don't spit"}},
{"fw_ld4_quick_i_0038","any",2,"reg=family",{1,"Mama, I'm hungry",2,"I know, baby",1,"Is there more?",2,"There's love, plenty of love, eat that"}},
{"fw_ld4_quick_i_0039","any",2,"reg=family",{1,"Grandpa, tell me about the war",2,"Which one?",1,"The big one",2,"It was long, and hot, and I lost my best friend, and I'd do it again to keep you safe"}},
{"fw_ld4_quick_j_0001","any",2,"reg=civilian,family,worker,rescue",{1,"I keep thinking about the last thing I said to her",2,"What was it?",1,"'Did you take out the trash?'",2,"Oh, Ben",1,"The LAST thing, a stupid question about trash"}},
{"fw_ld4_quick_j_0002","any",2,"reg=civilian,family,worker,rescue",{1,"I'm sorry I snored",2,"You didn't snore",1,"I did, I felt myself",2,"Then it was a tiny snore, like a mouse"}},
{"fw_ld4_quick_j_0003","any",2,"reg=civilian,family,worker,rescue",{1,"What's the oldest thing you own?",2,"A watch",1,"Whose?",2,"My granddad's, it stopped in 1971",1,"Keep it anyway",2,"Gives my hands something to do"}},
{"fw_ld4_quick_j_0004","any",2,"reg=civilian,family,worker,rescue",{1,"Do you like your name?",2,"It's fine",1,"Mine's terrible",2,"What's yours?",1,"Mildred",2,"It is charming, it's old, like a good cheese"}},
{"fw_ld4_quick_j_0005","any",2,"reg=civilian,family,worker,rescue",{1,"I hate being the youngest",2,"Why?",1,"Everyone treats me like a kid",2,"You are a kid",1,"I'm nineteen",2,"You are a very tired kid"}},
{"fw_ld4_quick_j_0006","any",2,"reg=civilian,family,worker,rescue|world=window,building",{1,"Close your eyes",2,"Why?",1,"And imagine your favorite room",2,"Okay",1,"What do you see?",2,"A kitchen, and a window, and someone washing dishes"}},
{"fw_ld4_quick_j_0007","any",2,"reg=civilian,family,worker,rescue",{1,"Is this what grown-ups feel like?",2,"What?",1,"Always tired and unsure",2,"Always, nobody tells you"}},
{"fw_ld4_quick_j_0008","any",2,"reg=civilian,family,worker,rescue",{1,"I'm sorry I can't help more",2,"You've been helping all day",1,"I haven't done anything",2,"You've been here, that's the help"}},
{"fw_ld4_quick_j_0009","any",2,"reg=civilian,family,worker,rescue",{1,"Look at my hands",2,"What about them?",1,"They look like my mother's",2,"Everyone's hands do, sooner or later"}},
{"fw_ld4_quick_j_0010","any",2,"reg=civilian,family,worker,rescue",{1,"Can I have a sip?",2,"Of what?",1,"Whatever you've got",2,"It's water",1,"Perfect"}},
{"fw_ld4_quick_j_0011","any",2,"reg=civilian,family,worker,rescue",{1,"Why is everything so loud?",2,"It's not loud",1,"Every footstep sounds like a drum",2,"That's because you're scared, breathe"}},
{"fw_ld4_quick_j_0012","any",2,"reg=civilian,family,worker,rescue",{1,"Do you want to hear a joke?",2,"I want to hear a quiet minute",1,"Fine, a quiet minute",2,"Thank you"}},
{"fw_ld4_quick_j_0013","any",2,"reg=civilian,family,worker,rescue",{1,"I've made a decision",2,"What is it?",1,"I'm going to stop being afraid",2,"Starting when?",1,"Starting right now, wait, no, tomorrow, no, starting in about an hour"}},
{"fw_ld4_quick_j_0014","any",2,"reg=civilian,family,worker,rescue",{1,"Hey, you made it",2,"Barely",1,"Take a minute, then tell me what happened",2,"I will, give me a minute, my hands are shaking"}},
{"fw_ld4_quick_j_0015","any",2,"reg=civilian,family,worker,rescue",{1,"What are you thinking about?",2,"Everything and nothing",1,"That's what I'm thinking about too",2,"Do you think there's a word for that?"}},
{"fw_ld4_quick_j_0016","any",2,"reg=civilian,family,worker,rescue",{1,"Could you hold my place?",2,"In what?",1,"In line, I need a minute",2,"There's no line",1,"Hold it anyway"}},
{"fw_ld4_quick_j_0017","any",2,"reg=civilian,family,worker,rescue",{1,"Tell me about your mother",2,"She was strict",1,"And?",2,"She made the best fried chicken, and she'd smack your hand if you reached before grace"}},
{"fw_ld4_quick_j_0018","any",2,"reg=civilian,family,worker,rescue",{1,"How's your faith holding?",2,"By a thread",1,"Same",2,"But a thread is something"}},
{"fw_ld4_quick_j_0019","any",2,"reg=civilian,family,worker,rescue",{1,"I never learned to cook",2,"You never will, you're awful",1,"I'm learning",2,"You burned water yesterday",1,"It was a very ambitious pot of water"}},
{"fw_ld4_quick_j_0020","any",2,"reg=civilian,family,worker,rescue",{1,"Is it Sunday or Monday?",2,"I don't know",1,"Does it matter?",2,"Not in the slightest, and that's the first good thing about all this"}},
{"fw_ld4_quick_j_0021","any",2,"reg=civilian,family,worker,rescue",{1,"You make me braver",2,"I don't do anything",1,"You do, you stand there, and I can't be a coward next to you",2,"Then I will stand very still"}},
{"fw_ld4_quick_j_0022","any",2,"reg=civilian,family,worker,rescue",{1,"Can I tell you something?",2,"Anything",1,"I'm glad it was you who found me",2,"I'm glad too"}},
{"fw_ld4_quick_j_0023","any",2,"reg=civilian,family,worker,rescue|tmp=fresh",{1,"Does it ever stop?",2,"What?",1,"The fear",2,"It gets quieter, it never stops"}},
{"fw_ld4_quick_j_0024","any",2,"reg=civilian,family,worker,rescue|tmp=fresh",{1,"I don't want to die",2,"Nobody does",1,"I'm too young",2,"That's what makes it so unfair"}},
{"fw_ld4_quick_j_0025","any",2,"reg=civilian,family,worker,rescue|tmp=seasoned",{1,"Same tired faces every morning",2,"Same tired faces, different tired hearts",1,"Poetic",2,"I'm just hungry"}},
{"fw_ld4_quick_j_0026","any",2,"reg=civilian,family,worker,rescue|tmp=seasoned",{1,"Remember when we complained about traffic?",2,"I'd love a traffic jam",1,"Me too, honking and all",2,"Honk for me, I'll pretend"}},
{"fw_ld4_quick_j_0027","any",2,"reg=law,swat",{1,"First time you drew your weapon?",2,"At a raccoon",1,"A raccoon?",2,"In a garbage can, I was twenty-two and jumpy"}},
{"fw_ld4_quick_j_0028","any",2,"reg=law,swat",{1,"You carry a lot of photographs",2,"They're my team",1,"Who's in the picture?",2,"Everyone who didn't make it"}},
{"fw_ld4_quick_j_0029","any",2,"reg=military,elite",{1,"Think we'll go home?",2,"Some of us",1,"Which some?",2,"The lucky some, and the stubborn some"}},
{"fw_ld4_quick_j_0030","any",2,"reg=military,elite|world=rain",{1,"Tell me about home",2,"It's green, and it smells like rain",1,"That's it?",2,"That's everything"}},
{"fw_ld4_quick_j_0031","any",2,"reg=military,elite",{1,"Hey, Sarge",2,"Yes?",1,"Thanks for being hard on us",2,"Somebody had to"}},
{"fw_ld4_quick_j_0032","any",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"Who's got my knife?",2,"It's behind your ear",1,"It is behind my ear",2,"Genius, you're a genius"}},
{"fw_ld4_quick_j_0033","any",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"What's the best thing you ever stole?",2,"A kiss",1,"From who?",2,"A girl in Louisville, she hit me, then she kissed back"}},
{"fw_ld4_quick_j_0034","any",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"You're a good shot",2,"Years of practice",1,"On what?",2,"Targets, mostly, sometimes squirrels, sometimes less cuddly things"}},
{"fw_ld4_quick_j_0035","any",2,"reg=family",{1,"Papa, you're strong",2,"Not as strong as I look",1,"You carried the whole bag",2,"With help from the hand of the Lord"}},
{"fw_ld4_quick_j_0036","any",2,"reg=family",{1,"Mama, I'm sorry I broke it",2,"It's okay, baby",1,"You're not mad?",2,"Things break, hearts mend"}},
{"fw_ld4_quick_j_0037","any",2,"reg=family",{1,"Pass the thread, dear",2,"Which color?",1,"Any, they're all faded now",2,"Then blue, because blue's my favorite"}},
{"fw_ld4_quick_k_0001","any",2,"reg=civilian,family,worker,rescue",{1,"You're awfully quiet today",2,"Just tired",1,"Tired, or sad?",2,"Both, can they share a room?"}},
{"fw_ld4_quick_k_0002","any",2,"reg=civilian,family,worker,rescue",{1,"I wanna cry and eat a cheeseburger",2,"At the same time?",1,"Preferably",2,"I'd watch that movie"}},
{"fw_ld4_quick_k_0003","any",2,"reg=civilian,family,worker,rescue",{1,"Check my back, any bites?",2,"Turn around",1,"Well?",2,"Clean, a mole, a big mole, and a lot of sweat"}},
{"fw_ld4_quick_k_0004","any",2,"reg=civilian,family,worker,rescue",{1,"Look at me",2,"I'm looking",1,"Do I look different?",2,"You look tired, and brave, and a little green"}},
{"fw_ld4_quick_k_0005","any",2,"reg=civilian,family,worker,rescue",{1,"Hold my hand, I'm going in",2,"Where?",1,"Into the dark",2,"Then I'm going in with you"}},
{"fw_ld4_quick_k_0006","any",2,"reg=civilian,family,worker,rescue",{1,"I made soup out of nothing",2,"Out of nothing?",1,"Salt, water, and a prayer",2,"It's better than the real thing"}},
{"fw_ld4_quick_k_0007","any",2,"reg=civilian,family,worker,rescue|hour=16,5",{1,"Do you think about tomorrow?",2,"Never",1,"Why not?",2,"Because tomorrow is a lie we tell to get through tonight"}},
{"fw_ld4_quick_k_0008","any",2,"reg=civilian,family,worker,rescue",{1,"I can hear my heart",2,"It's beating",1,"It's pounding",2,"It's alive, and that is the entire point"}},
{"fw_ld4_quick_k_0009","any",2,"reg=civilian,family,worker,rescue",{1,"Did you bring a spare?",2,"Spare what?",1,"Anything, socks, bullets, courage",2,"I brought a spare joke, it's terrible"}},
{"fw_ld4_quick_k_0010","any",2,"reg=civilian,family,worker,rescue",{1,"Sorry about earlier",2,"What about it?",1,"I was a jerk",2,"You were scared, we're all jerks when we're scared"}},
{"fw_ld4_quick_k_0011","any",2,"reg=civilian,family,worker,rescue",{1,"You look like your father",2,"Do I?",1,"Around the eyes",2,"He had sad eyes, but kind ones"}},
{"fw_ld4_quick_k_0012","any",2,"reg=civilian,family,worker,rescue",{1,"Do you think we'll be remembered?",2,"By who?",1,"By whoever's left",2,"Then let's do something worth remembering"}},
{"fw_ld4_quick_k_0013","any",2,"reg=civilian,family,worker,rescue",{1,"I'm so thirsty I could cry",2,"Cry, then, it's water",1,"Ha ha",2,"I'm serious, drink your tears"}},
{"fw_ld4_quick_k_0014","any",2,"reg=civilian,family,worker,rescue",{1,"Wait, I forgot something",2,"What?",1,"My name",2,"It's Carol",1,"Carol, right... sorry, I hit my head earlier"}},
{"fw_ld4_quick_k_0015","any",2,"reg=civilian,family,worker,rescue",{1,"Why do you wear your hair like that?",2,"It hides my face",1,"Why hide?",2,"Because I'm not who I used to be"}},
{"fw_ld4_quick_k_0016","any",2,"reg=civilian,family,worker,rescue",{1,"You want me to carry that?",2,"I'm fine",1,"You're limping",2,"I'm limping with dignity"}},
{"fw_ld4_quick_k_0017","any",2,"reg=civilian,family,worker,rescue",{1,"Did you hear what he said?",2,"I did",1,"Do you believe it?",2,"I want to, which is almost the same thing"}},
{"fw_ld4_quick_k_0018","any",2,"reg=civilian,family,worker,rescue",{1,"I hate waiting",2,"Same",1,"Let's play a game",2,"Name one fruit for every letter",1,"Apple",2,"Banana"}},
{"fw_ld4_quick_k_0019","any",2,"reg=civilian,family,worker,rescue",{1,"What's the longest you've gone without talking?",2,"Three days",1,"And?",2,"And I forgot how my voice sounded"}},
{"fw_ld4_quick_k_0020","any",2,"reg=civilian,family,worker,rescue",{1,"Your hands are cold",2,"Always",1,"Put them in my pockets",2,"Thanks, that's the nicest thing today"}},
{"fw_ld4_quick_k_0021","any",2,"reg=civilian,family,worker,rescue",{1,"Do you believe in ghosts?",2,"Now I do",1,"I saw one last night",2,"Where?",1,"In the mirror"}},
{"fw_ld4_quick_k_0022","any",2,"reg=civilian,family,worker,rescue",{1,"What's your earliest memory?",2,"My mother singing",1,"What song?",2,"I don't remember the words, just the sound"}},
{"fw_ld4_quick_k_0023","any",2,"reg=civilian,family,worker,rescue",{1,"Don't look back",2,"I won't",1,"Promise?",2,"I'll try, honestly, I'll try"}},
{"fw_ld4_quick_k_0024","any",2,"reg=civilian,family,worker,rescue",{1,"Sit with me",2,"For how long?",1,"As long as it takes",2,"Until the sun comes up?",1,"Until you feel better"}},
{"fw_ld4_quick_k_0025","any",2,"reg=civilian,family,worker,rescue",{1,"I could eat a horse",2,"Don't say that",1,"A figure of speech",2,"Hah, not these days"}},
{"fw_ld4_quick_k_0026","any",2,"reg=civilian,family,worker,rescue",{1,"Is it going to be okay?",2,"Honestly?",1,"Honestly",2,"I don't know, but I'll be here, whatever happens"}},
{"fw_ld4_quick_k_0027","any",2,"reg=civilian,family,worker,rescue|tmp=fresh",{1,"I'm never going to see my house again",2,"Maybe you will",1,"Do you think so?",2,"I think the house is waiting, houses are patient"}},
{"fw_ld4_quick_k_0028","any",2,"reg=civilian,family,worker,rescue|tmp=fresh",{1,"Do you ever feel like a little kid?",2,"Right now",1,"Me too",2,"Let's hold hands, and pretend we're not scared"}},
{"fw_ld4_quick_k_0029","any",2,"reg=civilian,family,worker,rescue|tmp=seasoned",{1,"How are you not tired?",2,"I'm exhausted",1,"You hide it well",2,"I've had practice hiding everything"}},
{"fw_ld4_quick_k_0030","any",2,"reg=civilian,family,worker,rescue|tmp=seasoned",{1,"Anything good in the bag?",2,"A sock, a spoon, a promise",1,"A promise?",2,"I promised to bring it home"}},
{"fw_ld4_quick_k_0031","any",2,"reg=law,swat",{1,"My partner used to sing off-key",2,"Used to?",1,"He's gone, I'd give anything to hear it again",2,"I'm sorry"}},
{"fw_ld4_quick_k_0032","any",2,"reg=law,swat",{1,"Think we're doing any good?",2,"Some",1,"Enough?",2,"It's never enough, but it's something"}},
{"fw_ld4_quick_k_0033","any",2,"reg=military,elite",{1,"I miss my guitar",2,"Do you play?",1,"Badly",2,"I'd listen"}},
{"fw_ld4_quick_k_0034","any",2,"reg=military,elite",{1,"Corporal, I'm scared",2,"Good",1,"Good?",2,"It means you're not stupid"}},
{"fw_ld4_quick_k_0035","any",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"You ever been in love?",2,"Once",1,"What happened?",2,"She had a husband, and he had a shotgun"}},
{"fw_ld4_quick_k_0036","any",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"Tell me a secret",2,"I hate heights",1,"That's it?",2,"It's more than you know, it's my deepest fear"}},
{"fw_ld4_quick_k_0037","any",2,"reg=family",{1,"Papa, are we poor now?",2,"We're rich in other ways",1,"Like what?",2,"We have each other, and a pot of beans"}},
{"fw_ld4_quick_k_0038","any",2,"reg=family",{1,"Mama, will you braid my hair?",2,"Always",1,"Not too tight",2,"Never too tight, baby"}},
{"fw_ld4_quick_l_0001","any",2,"reg=civilian,family,worker,rescue",{1,"Whatever you do, don't look down",2,"Why not?",1,"Because I just did, and I regret it",2,"Thanks for the warning, now I definitely will"}},
{"fw_ld4_quick_l_0002","any",2,"reg=civilian,family,worker,rescue",{1,"Hey, you want some of my tobacco?",2,"I don't smoke",1,"Chew?",2,"I don't chew",1,"Then what do you do?",2,"Mostly I worry"}},
{"fw_ld4_quick_l_0003","any",2,"reg=civilian,family,worker,rescue",{1,"I took a nap and dreamed we were at a barbecue",2,"Who was grilling?",1,"You were, with a spatula in one hand and a rifle in the other",2,"Sounds like me"}},
{"fw_ld4_quick_l_0004","any",2,"reg=civilian,family,worker,rescue|world=building",{1,"What if the Army comes back?",2,"Good",1,"What if they take us away?",2,"Even better, somewhere with walls",1,"And food?",2,"And food, God willing"}},
{"fw_ld4_quick_l_0005","any",2,"reg=civilian,family,worker,rescue",{1,"You okay? You look pale",2,"I'm fine",1,"You look green",2,"I'm fine-green, it's a color"}},
{"fw_ld4_quick_l_0006","any",2,"reg=civilian,family,worker,rescue",{1,"Are you a morning person?",2,"I used to be",1,"And now?",2,"Now I'm a survive-until-noon person"}},
{"fw_ld4_quick_l_0007","any",2,"reg=civilian,family,worker,rescue",{1,"Sorry, I stepped on your foot",2,"It's fine",1,"It's not, I'm a klutz",2,"Everyone's a klutz in the dark"}},
{"fw_ld4_quick_l_0008","any",2,"reg=civilian,family,worker,rescue",{1,"Do you want to know a secret?",2,"Always",1,"I'm not as old as I look",2,"How old are you?",1,"Forty-one, the apocalypse ages you in dog years"}},
{"fw_ld4_quick_l_0009","any",2,"reg=civilian,family,worker,rescue",{1,"Don't let go",2,"I'm not going to",1,"Promise",2,"Promise, now step, one foot, there"}},
{"fw_ld4_quick_l_0010","any",2,"reg=civilian,family,worker,rescue",{1,"I made a vow",2,"To who?",1,"To myself, if I live through this, I'll call my brother",2,"Then you'll live"}},
{"fw_ld4_quick_l_0011","any",2,"reg=civilian,family,worker,rescue",{1,"I miss silly things",2,"Like?",1,"Commercials, junk mail, bad radio hosts",2,"I miss traffic reports"}},
{"fw_ld4_quick_l_0012","any",2,"reg=civilian,family,worker,rescue",{1,"Is it wrong to want a hot shower more than world peace?",2,"Not at all",1,"I'd trade world peace for a hot shower",2,"Don't tell the Army that"}},
{"fw_ld4_quick_l_0013","any",2,"reg=civilian,family,worker,rescue",{1,"You think that guy has a plan?",2,"Which guy?",1,"The one in charge",2,"He has a plan, it's called 'wing it'"}},
{"fw_ld4_quick_l_0014","any",2,"reg=civilian,family,worker,rescue|world=water",{1,"I wish we had a map",2,"We have a map",1,"That's a paper placemat",2,"It's got a drawing of a river on it"}},
